class MutableSequence(Sequence):
    """All the operations on a read-write sequence.

    Concrete subclasses must provide __new__ or __init__,
    __getitem__, __setitem__, __delitem__, __len__, and insert().
    """

    __slots__ = ()

    @abstractmethod
    def __setitem__(self, index, value):
        raise IndexError

    @abstractmethod
    def __delitem__(self, index):
        raise IndexError

    @abstractmethod
    def insert(self, index, value):
        'S.insert(index, value) -- insert value before index'
        raise IndexError

    def append(self, value):
        'S.append(value) -- append value to the end of the sequence'
        self.insert(len(self), value)

    def clear(self):
        'S.clear() -> None -- remove all items from S'
        try:
            while True:
                self.pop()
        except IndexError:
            pass

    def reverse(self):
        'S.reverse() -- reverse *IN PLACE*'
        n = len(self)
        for i in range(n//2):
            self[i], self[n-i-1] = self[n-i-1], self[i]

    def extend(self, values):
        'S.extend(iterable) -- extend sequence by appending elements from the iterable'
        if values is self:
            values = list(values)
        for v in values:
            self.append(v)

    def pop(self, index=-1):
        '''S.pop([index]) -> item -- remove and return item at index (default last).
           Raise IndexError if list is empty or index is out of range.
        '''
        v = self[index]
        del self[index]
        return v

    def remove(self, value):
        '''S.remove(value) -- remove first occurrence of value.
           Raise ValueError if the value is not present.
        '''
        del self[self.index(value)]

    def __iadd__(self, values):
        self.extend(values)
        return self


MutableSequence.register(list)
MutableSequence.register(bytearray)  # Multiply inheriting, see ByteString

import drjit as _dr
import sys
import inspect
from typing import Callable, Union
from functools import wraps as _wraps
from collections.abc import Mapping, Sequence

VAR_TYPE_NAME = [
    "Void",    "Bool",  "Int8",  "UInt8", "Int16",
    "UInt16",  "Int",   "UInt",  "Int64", "UInt64", "Pointer",
    "Float16", "Float", "Float64"
]

VAR_TYPE_SUFFIX = [
    "???", "b", "i8",  "u8",  "i16", "u16", "i", "u",
    "i64", "u64", "p", "f16", "f", "f64"
]


def array_name(prefix, vt, shape, scalar):
    """
    Determines the name of an array (e.g. Float32, ArrayXf32, etc.). This
    function is used when arrays are created during initialization of the Dr.Jit
    extension module, and during implicit type promotion where array types are
    determined dynamically.

    Parameter ``prefix`` (``str``):
        Array flavor prefix (Array/Matrix/Complex/Quaternion)

    Parameter ``vt`` (``drjit.VarType``):
        Underlying scalar type (e.g. ``VarType.Int32``) of the desired array

    Parameter ``shape`` (``Tuple[int]``):
        Size per dimension

    Parameter ``scalar`` (``bool``):
        Arrays in the ``drjit.scalar.*`` module use a different depth
        convention, which is indicated via this parameter.
    """

    if not scalar and not prefix == 'Tensor':
        shape = shape[:-1]
    if prefix == "Matrix":
        if vt != _dr.VarType.Bool:
            shape = shape[1:]
        else:
            prefix = "Array"

    if len(shape) == 0 and prefix != "Tensor":
        return VAR_TYPE_NAME[int(vt)]

    return "%s%s%s" % (
        prefix,
        "".join(repr(s) if s != _dr.Dynamic else "X" for s in shape),
        VAR_TYPE_SUFFIX[int(vt)]
    )


def array_from_dlpack(t, capsule):
    descr = _dr.detail.from_dlpack(capsule)

    device_type = descr["device_type"]
    data = descr["data"]
    dtype = descr["dtype"]
    shape = descr["shape"]
    ndim = len(shape)
    strides = list(descr["strides"])

    if strides is None:
        tmp = 1
        strides = [0] * ndim
        for i in reversed(range(ndim)):
            strides[i] = tmp
            tmp *= shape[i]

    if t.IsCUDA and device_type != 2:
        raise _dr.Exception("Cannot create an Dr.Jit GPU array from a "
                             "DLPack CPU tensor!")
    elif not t.IsCUDA and device_type != 1:
        raise _dr.Exception("Cannot create an Dr.Jit CPU array from a "
                            "DLPack GPU tensor!")

    if dtype != t.Type:
        raise _dr.Exception("Incompatible type!")

    shape_target = list(reversed(_dr.shape(t())))
    if len(shape_target) != ndim:
        raise _dr.Exception("Incompatible dimension!")
    for i in range(ndim):
        if shape_target[i] != shape[i] and shape_target[i] != 0:
            raise _dr.Exception("Incompatible shape!")

    value = t
    while issubclass(value.Value, _dr.ArrayBase):
        value = value.Value

    descr["consume"](capsule)
    data = value.map_(data, _dr.prod(shape), descr["release"])

    def load(t, i, offset):
        size = shape[-1 - i]
        stride = strides[-1 - i]

        # Stride size is "irrelevant" with unit dimension, some frameworks set
        # the stride to 0 or 1
        if size == 1:
            stride = strides[-i] * shape[-i] if i != 0 else 1
            strides[-1 - i] = stride

        if i == ndim - 1:
            if type(offset) is int and stride == 1:
                return data
            else:
                i = _dr.arange(_dr.int32_array_t(t), size)
                return t.gather_(data, offset + stride * i, True, False)
        else:
            result = t()
            for j in range(size):
                result[j] = load(t.Value, i + 1, offset + stride * j)
            return result

    return load(t, 0, 0)


def sub_len(o):
    ol = len(o[0])
    try:
        for i in range(1, len(o)):
            if len(o[i]) != ol:
                return -1
    except Exception:
        return -1
    return ol


def array_init(self, args):
    """
    This generic initialization routine initializes an arbitrary Dr.Jit array
    from a variable-length argument list (which could be a scalar broadcast, a
    component list, or a NumPy/PyTorch/Tensorflow array..)
    """
    n = len(args)
    if n == 0:
        return

    size = self.Size
    value_type = self.Value
    dynamic = size == _dr.Dynamic
    err = None

    try:
        if n == 1:
            o = args[0]
            t = type(o)
            mod = t.__module__
            name = t.__name__
            is_array = issubclass(t, _dr.ArrayBase)
            is_static_array = is_array and not o.Size == _dr.Dynamic
            is_sequence = issubclass(t, Sequence) and not issubclass(t, str)

            # Matrix initialization from nested list
            if is_sequence and self.IsMatrix and \
                len(o) == size and sub_len(o) == size:
                for x in range(size):
                    for y in range(size):
                        self[x, y] = value_type.Value(o[x][y])
            elif is_array or is_sequence:
                os = len(o)
                if dynamic:
                    size = os
                    self.init_(size)

                if size == 0:
                    pass
                elif size != os or value_type is t:
                    # Size mismatch!
                    if self.IsMatrix and getattr(t, "IsMatrix", False):
                        # If both are matrices, copy the top-left block
                        for x in range(size):
                            for y in range(size):
                                if x < o.Size and y < o.Size:
                                    self[x, y] = value_type.Value(o[x, y])
                                else:
                                    self[x, y] = value_type.Value(1 if x == y else 0)
                    elif self.IsMatrix and value_type is t:
                        for x in range(size):
                            self[x] = o
                    else:
                        # Otherwise, try to broadcast to all entries
                        self.broadcast_(value_type(o)
                                        if not issubclass(t, value_type)
                                        and not self.IsMatrix else o)
                else:
                    # Size matches, copy element by element
                    if self.IsJIT and getattr(t, "IsJIT", False) and \
                       self.Depth == 1 and t.Depth == 1:
                        raise _dr.Exception(
                            "Refusing to do an extremely inefficient "
                            "element-by-element array conversion from type %s "
                            "to %s. Did you forget a cast or detach operation?"
                            % (str(type(o)), str(type(self))))

                    if isinstance(o[0], value_type) or self.IsMatrix:
                        for i in range(size):
                            self.set_entry_(i, o[i])
                    else:
                        for i in range(size):
                            self.set_entry_(i, value_type(o[i]))
            elif issubclass(t, (int, float)) and (not self.IsJIT or self.Depth > 1):
                if dynamic:
                    size = 1
                    self.init_(size)
                self.broadcast_(o)
            elif issubclass(t, complex) and self.IsComplex:
                self.set_entry_(0, o.real)
                self.set_entry_(1, o.imag)
            elif mod == "numpy":
                import numpy as np

                s1 = tuple(reversed(_dr.shape(self)))
                s2 = o.shape

                # Remove unnecessary outer dimension is possible
                if s2[0] == 1 and len(s2) > 1:
                    o = o[0, ...]
                    s2 = o.shape

                if o.dtype == np.complex64:
                    s2 = (*s2, 2)
                    o = o.view(np.float32).reshape(s2)
                elif o.dtype == np.complex128:
                    s2 = (*s2, 2)
                    o = o.view(np.float64).reshape(s2)

                if o.dtype != self.Type.NumPy:
                    o = o.astype(self.Type.NumPy)

                dim1 = len(s1)
                dim2 = len(s2)

                # Numpy array might have one dimension less when initializing dynamic arrays
                if not dim1 == dim2 and not (dim1 == dim2 + 1 and self.IsDynamic):
                    raise _dr.Exception("Incompatible dimension!")
                for i in reversed(range(dim2)):
                    if s1[i] != s2[i] and s1[i] != 0:
                        raise _dr.Exception("Incompatible shape!")

                if dim1 == 0:
                    pass
                elif dim1 == 1 and self.IsDynamic:
                    o = np.ascontiguousarray(o)
                    holder = (o, o.__array_interface__["data"][0])
                    self.assign(self.load_(holder[1], s2[0]))
                else:
                    for i in range(s1[-1]):
                        if dim2 == 1 and self.IsDynamic:
                            self.set_entry_(i, value_type.Value(o[i]))
                        else:
                            self.set_entry_(i, value_type(o[..., i]))

            elif mod == "builtins" and name == "PyCapsule":
                self.assign(array_from_dlpack(type(self), o))
            elif mod == "torch":
                from torch.utils.dlpack import to_dlpack
                self.assign(array_from_dlpack(type(self), to_dlpack(o)))
            elif mod.startswith("tensorflow."):
                from tensorflow.experimental.dlpack import to_dlpack
                self.assign(array_from_dlpack(type(self), to_dlpack(o)))
            elif mod.startswith("jax.") or mod.startswith("jaxlib."):
                from jax.dlpack import to_dlpack
                self.assign(array_from_dlpack(type(self), to_dlpack(o)))
            else:
                raise _dr.Exception("Don\"t know how to create an Dr.Jit array "
                                      "from type \"%s.%s\"!" % (mod, name))
        elif n == size or dynamic:
            if dynamic:
                size = n
                self.init_(size)
            for i in range(size):
                self.set_entry_(i, value_type(args[i]))
        elif self.IsMatrix and n == self.Size * self.Size:
            tbl = [[args[i*self.Size + j] for i in range(self.Size)]
                   for j in range(self.Size)]
            array_init(self, tbl)
        else:
            raise _dr.Exception("Invalid size!")
    except Exception as e:
        err = e

    if err is not None:
        if dynamic:
            raise TypeError("%s constructor expects: arbitrarily many values "
                            "of type \"%s\", a matching list/tuple, or a NumPy/"
                            "PyTorch/TF/Jax array." % (type(self).__name__,
                                                       value_type.__name__)) from err
        else:
            raise TypeError("%s constructor expects: %s%i values "
                            "of type \"%s\", a matching list/tuple, or a NumPy/"
                            "PyTorch/TF/Jax array." % (type(self).__name__, "" if
                                                       size == 1 else "1 or ", size,
                                                       value_type.__name__)) from err


def tensor_init(tensor_type, obj):
    mod = type(obj).__module__
    if 'tensorflow' in mod:
        import tensorflow as tf
        return tensor_type(tensor_type.Array(tf.reshape(obj, [-1])), obj.shape)
    elif mod.startswith('torch'):
        shape = obj.shape if len(obj.shape) > 0 else [1]
        return tensor_type(tensor_type.Array(obj.flatten()), shape)
    elif mod.startswith(('numpy', 'jax')):
        return tensor_type(tensor_type.Array(obj.ravel()), obj.shape)
    else:
        info = getattr(obj, '__array_interface__', None)
        if info is not None:
            shape = info['shape']
            typestr = str(info['typestr'])[3:-1]
            cls = tensor_type.Array
            if typestr != tensor_type.Array.Type.NumPy:
                name = None
                for v in VAR_TYPE_NAME:
                    t = getattr(_dr.VarType, v, None)
                    if t and t.NumPy == typestr:
                        name = array_name('Array', t, [_dr.Dynamic], False)
                        break
                if name and hasattr(mod, name):
                    cls = getattr(mod, name)
                else:
                    import numpy as np
                    np_data = np.array(obj).astype(tensor_type.Array.Type.NumPy)
                    return tensor_init(tensor_type, np_data)

            data = cls.load_(info['data'][0], _dr.prod(shape))
            return tensor_type(tensor_type.Array(data), shape)
        else:
            raise TypeError("TensorXf: expect an array that implements the "
                            "array interface protocol!")

@property
def prop_x(self):
    return self[0]


@prop_x.setter
def prop_x(self, value):
    self[0] = value


@property
def prop_y(self):
    return self[1]


@prop_y.setter
def prop_y(self, value):
    self[1] = value


@property
def prop_z(self):
    return self[2]


@prop_z.setter
def prop_z(self, value):
    self[2] = value


@property
def prop_w(self):
    return self[3]


@prop_w.setter
def prop_w(self, value):
    self[3] = value


@property
def prop_xyz(self):
    return self.Imag(self[0], self[1], self[2])


@prop_xyz.setter
def prop_xyz(self, value):
    if not isinstance(value, self.Imag):
        value = self.Imag(value)
    self.x = value.x
    self.y = value.y
    self.z = value.z


def array_configure(cls, shape, type_, value):
    """Populates an Dr.Jit array class with extra type trait fields"""
    depth = 1

    cls.Value = value
    cls.Type = type_
    cls.Shape = shape
    cls.Size = shape[0]
    cls.IsDynamic = cls.Size == _dr.Dynamic or \
        getattr(value, "IsDynamic", False)

    while issubclass(value, _dr.ArrayBase):
        value = value.Value
        depth += 1

    cls.Depth = depth
    cls.Scalar = value
    cls.IsDrJit = True
    cls.IsMask = issubclass(value, bool)
    cls.IsIntegral = issubclass(value, int) and not cls.IsMask
    cls.IsFloat = issubclass(value, float)
    cls.IsArithmetic = cls.IsIntegral or cls.IsFloat
    cls.IsSigned = cls.IsFloat or "i" in VAR_TYPE_SUFFIX[int(type_)]

    mod = cls.__module__
    cls.IsScalar = mod.startswith("drjit.scalar")
    cls.IsPacket = mod.startswith("drjit.packet")
    cls.IsDiff = mod.endswith(".ad")
    cls.IsLLVM = mod.startswith("drjit.llvm")
    cls.IsCUDA = mod.startswith("drjit.cuda")
    cls.IsJIT = cls.IsLLVM or cls.IsCUDA

    name = cls.__name__
    cls.IsMatrix = "Matrix" in name
    cls.IsComplex = "Complex" in name
    cls.IsQuaternion = "Quaternion" in name
    cls.IsTensor = "Tensor" in name
    cls.IsSpecial = cls.IsMatrix or cls.IsComplex or cls.IsQuaternion
    cls.IsVector = cls.Size != _dr.Dynamic and not \
        (cls.IsPacket and cls.Depth == 1) and not cls.IsSpecial

    prefix = name
    for i, c in enumerate(name):
        if c.isdigit() or c == 'X':
            prefix = name[:i]
            break
    mask_name = prefix

    cls.Prefix = prefix

    if cls.IsSpecial:
        mask_name = 'Array'

        if cls.IsComplex:
            cls.real = prop_x
            cls.imag = prop_y
        elif cls.IsQuaternion:
            cls.real = prop_w
            cls.imag = prop_xyz
            cls.Imag = getattr(sys.modules.get(mod),
                               name.replace("Quaternion4", "Array3"))
            cls.Complex = getattr(sys.modules.get(mod),
                                  name.replace("Quaternion4", "Complex2"))

    if cls.IsTensor:
        cls.__getitem__ = _dr.detail.tensor_getitem
        cls.__setitem__ = _dr.detail.tensor_setitem

    elif (not cls.IsSpecial or cls.IsQuaternion) \
            and not cls.Size == _dr.Dynamic:
        if cls.Size > 0:
            cls.x = prop_x
        if cls.Size > 1:
            cls.y = prop_y
        if cls.Size > 2:
            cls.z = prop_z
        if cls.Size > 3:
            cls.w = prop_w

    cls.MaskType = getattr(
        sys.modules.get(mod),
        array_name(mask_name, _dr.VarType.Bool, cls.Shape, cls.IsScalar))


def _loop_process_state(value: type, in_state: list, out_state: list,
                        write: bool, in_struct: bool = False):
    '''
    This helper function is used by ``drjit.*.Loop`` to collect the set of loop
    state variables and ensure that their types stay consistent over time. It
    traverses a python object tree in ``value`` and writes state variable
    indices to ``out_state``. If provided, it performs a consistency check
    against the output of a prior call provided via ``in_state``. If ``write``
    is set to ``True``, it mutates the input value based on the information in
    ``in_state``.
    '''
    t = type(value)

    out_state.append(t)
    if in_state:
        assert len(in_state) > 0
        t_old = in_state.pop()
        if t is not t_old:
            raise _dr.Exception(
                "loop_process_state(): the type of loop state variables must "
                "remain the same throughout the loop. However, one of the "
                "supplied variables changed from type %s to %s!"
                % (t_old.__name__, t.__name__))

    if issubclass(t, tuple) or issubclass(t, list):
        for entry in value:
            _loop_process_state(entry, in_state, out_state, write, in_struct)
        return

    if _dr.is_tensor_v(t):
        _loop_process_state(value.array, in_state, out_state, write, in_struct)
    elif _dr.is_jit_v(t):
        if t.Depth > 1:
            for i in range(len(value)):
                _loop_process_state(value.entry_ref_(i), in_state,
                                    out_state, write, in_struct)
        else:
            index = value.index
            index_ad = value.index_ad if t.IsDiff else 0

            if index_ad != 0 and _dr.flag(_dr.JitFlag.LoopRecord):
                raise _dr.Exception(
                    "loop_process_state(): one of the supplied loop state variables "
                    "of type %s is attached to the AD graph (i.e., grad_enabled(..) "
                    "is true). However, propagating derivatives through multiple "
                    "iterations of a recorded loop is not supported (and never "
                    "will be). Please see the documentation on differentiating loops "
                    "for details and suggested alternatives." % t.__name__)

            if index == 0:
                raise _dr.Exception(
                    "loop_process_state(): one of the supplied loop state "
                    "variables of type %s is uninitialized!" % t.__name__)

            ad_float_precision = value.Type.Size * 8 if (t.IsDiff and t.IsFloat) else 0
            out_state.append((index, index_ad, ad_float_precision))

            if in_state:
                assert len(in_state) > 0
                index, index_ad, _ = in_state.pop()

                if write:
                    value.set_index_(index)
                    if t.IsDiff:
                        value.set_index_ad_(index_ad)
    elif _dr.is_struct_v(t):
        for k, v in t.DRJIT_STRUCT.items():
            _loop_process_state(getattr(value, k), in_state, out_state, write, True)
    elif hasattr(value, 'loop_put') or value is None:
        pass
    elif not in_struct:
        raise _dr.Exception(
            "loop_process_state(): one of the provided loop state variables "
            "was of type '%s', which is not allowed (you must use Dr.Jit "
            "arrays/structs that are managed by the JIT compiler)"
            % t.__name__)


def loop_process_state(loop, funcs, state, write):
    if len(state) == 0:
        old_state = None

        for func in funcs:
            values = func()

            if isinstance(values, Sequence) and not isinstance(values, str):
                for value in values:
                    if hasattr(value, 'loop_put'):
                        value.loop_put(loop)

            # Automatically label loop variables
            cv = inspect.getclosurevars(func)
            _dr.set_label(**cv.globals)
            _dr.set_label(**cv.nonlocals)

            del values

        assert old_state is None or len(old_state) == 0
    else:
        old_state = list(state)
        old_state.reverse()

    del loop # Keep 'loop' out of the garbage collector's reach

    state.clear()

    for func in funcs:
        _loop_process_state(func(), old_state, state, write)

    assert old_state is None or len(old_state) == 0


def slice_tensor(shape, indices, uint32):
    """
    This function takes an array shape (integer tuple) and a tuple containing
    slice indices. It returns the resulting array shape and a flattened 32-bit
    unsigned integer array containing element indices.
    """
    components = []
    ellipsis = False
    none_count = 0
    shape_offset = 0

    for v in indices:
        if v is None:
            none_count += 1

    for v in indices:
        if v is None:
            components.append(None)
            continue

        if shape_offset >= len(shape):
            raise IndexError("slice_tensor(): too many indices specified!")

        size = shape[shape_offset]

        if isinstance(v, int):
            # Simple integer index, handle wrap-around
            if v < 0:
                v += size
            if v >= size:
                raise IndexError("slice_tensor(): index %i for dimension %i is "
                                 "out of range (size = %i)!" %
                                 (v, len(components), size))
            components.append((v, v+1, 1))
        elif isinstance(v, slice):
            # Rely on Python's slice.indices() function to determine everything
            components.append(v.indices(size))
        elif _dr.is_dynamic_array_v(v) and _dr.is_integral_v(v):
            if _dr.is_signed_v(v):
                v = uint32(_dr.select(v >= 0, v, v + size))
            components.append(v)
        elif isinstance(v, Sequence) and not isinstance(v, str):
            components.append(uint32([v2 if v2 >= 0 else v2 + size for v2 in v]))
        elif v is Ellipsis:
            if ellipsis:
                raise IndexError("slice_tensor(): multiple ellipses (...) are not allowed!")
            ellipsis = True

            for j in range(len(shape) - len(indices) + none_count + 1):
                components.append((0, shape[shape_offset], 1))
                shape_offset += 1
            continue
        else:
            raise TypeError("slice_tensor(): type '%s' cannot be used to index "
                            "into a tensor!" % type(v).__name__)
        shape_offset += 1

    # Implicit ellipsis
    for j in range(len(shape) - shape_offset):
        components.append((0, shape[shape_offset], 1))
        shape_offset += 1

    # Compute total index size
    size_out = 1
    shape_out = []
    for comp in components:
        if comp is None:
            shape_out.append(1)
        else:
            size = len(comp if isinstance(comp, uint32) else range(*comp))
            if size != 1:
                shape_out.append(size)
                size_out *= shape_out[-1]
    shape_out = tuple(shape_out)

    index_tmp = _dr.arange(uint32, size_out)
    index_out = uint32()

    if size_out > 0:
        size_out = 1
        index_out = uint32(0)
        shape_offset = len(shape)-1

        for i in reversed(range(len(components))):
            comp = components[i]
            if comp is None:
                continue
            size = len(comp if isinstance(comp, uint32) else range(*comp))
            index_next = index_tmp // size
            index_rem = index_tmp - index_next * size

            if isinstance(comp, uint32):
                index_val = _dr.gather(uint32, comp, index_rem)
            else:
                if comp[0] >= 0 and comp[2] >= 0:
                    index_val = comp[0] + comp[2] * index_rem
                else:
                    index_val = uint32(comp[0] + comp[2] * _dr.int32_array_t(index_rem)(index_rem))

            index_out += index_val * size_out
            index_tmp = index_next
            size_out *= shape[shape_offset]
            shape_offset -= 1

    return shape_out, index_out


def tensor_getitem(tensor, slice_arg):
    if not isinstance(slice_arg, tuple):
        slice_arg = (slice_arg,)
    tensor_t = type(tensor)
    shape, index = slice_tensor(tensor.shape, slice_arg, tensor_t.Index)
    return tensor_t(_dr.gather(tensor_t.Array, tensor.array, index), shape)


def tensor_setitem(tensor, slice_arg, value):
    if not isinstance(slice_arg, tuple):
        slice_arg = (slice_arg,)
    tensor_t = type(tensor)
    shape, index = slice_tensor(tensor.shape, slice_arg, tensor_t.Index)
    _dr.scatter(target=tensor.array, value=value, index=index)


def traverse(traverse_static_array=True, traverse_tensor=True):
    '''
    Function decorator that traverses nested datastructures (e.g. dicts, lists,
    Dr.Jit struct, ...) and applies the decorated function to all JIT arrays
    it encounters.
    '''
    def wrapper(func: Callable):
        @_wraps(func)
        def traverse(*args, **kwargs):
            a = args[0]
            ta = type(a)

            # Heuristic defining whether b should be sliced according to args[0]
            def should_slice(b):
                if not isinstance(b, ta):
                    return False
                if isinstance(a, Sequence):
                    if len(b) != len(a):
                        return False
                    if len(a) > 0 and not isinstance(b[0], type(a[0])):
                        return False
                return True

            # Apply slicer to all arguments whose type match the one of the first argument.
            def slice_args(slicer):
                return tuple(slicer(args[i]) if should_slice(args[i]) else args[i] for i in range(len(args)))

            if _dr.depth_v(a) > 1 and traverse_static_array:
                res = ta()
                for i in range(_dr.size_v(a)):
                    v = traverse(*slice_args(lambda x: x[i]), **kwargs)
                    if v is not None:
                        res[i] = v
                return res
            elif isinstance(a, Sequence) and not isinstance(a, str):
                return ta(traverse(*slice_args(lambda x: x[i]), **kwargs) for i in range(len(a)))
            elif isinstance(a, Mapping):
                return { k: traverse(*slice_args(lambda x: x[k]), **kwargs) for k in a.keys() }
            elif _dr.is_struct_v(a):
                res = ta()
                for k in ta.DRJIT_STRUCT.keys():
                    v = traverse(*slice_args(lambda x: getattr(x, k)), **kwargs)
                    if v is not None:
                        setattr(res, k, v)
                return res
            elif _dr.is_tensor_v(a) and traverse_tensor:
                v = traverse(*slice_args(lambda x: x.array), **kwargs)
                return ta(v, a.shape) if v is not None else None
            elif _dr.is_jit_v(a):
                return func(*args, **kwargs)
            else:
                return a

        return traverse

    return wrapper


@traverse()
def apply_cpp(arg, func, diff=True):
    '''
    Apply a C++ function to data structures containing JIT variables. The C++
    lambda must take as input the index of the JIT variable. It can optionally
    return a new index in which case a new data structure will be constructed
    carrying the new JIT variables.
    '''
    res = type(arg)()
    idx = func(arg.index)
    if isinstance(idx, int):
        res.set_index_(idx)
        if diff and _dr.is_diff_v(arg):
            res.set_index_ad_(arg.index_ad)
    return res


@traverse()
def diff_vars(arg, indices, check_grad_enabled=True):
    """
    Extract indices of differentiable variables.
    """
    if _dr.is_diff_v(arg) and arg.IsFloat:
        if arg.index_ad != 0 and (not check_grad_enabled or arg.grad_enabled_()):
            indices.append(arg.index_ad)


def get_args_values(f, *args, **kwargs):
    '''
    Given a function, a tuple of positional arguments and a dict of keyword
    arguments, return the full tuple of positional arguments, including default
    values and keyword arguments at the right position.

    Here is a simple example:

        def f(a, b, c=1, d=2):
            pass
        get_args_values(f, 6, 5, d=4) # returns (4, 5, 1, 4)
    '''
    argcount = f.__code__.co_argcount
    argnames = f.__code__.co_varnames[:argcount]
    defaults = f.__defaults__ if f.__defaults__ else []

    assert len(args) + len(defaults) >= argcount

    m = {n: None for n in argnames}
    for i, a in enumerate(reversed(defaults)):
        m[argnames[-(i + 1)]] = a
    for i, a in enumerate(args):
        m[argnames[i]] = a
    for k, v in kwargs.items():
        m[k] = v

    return tuple(m.values())

from typing import Callable, Union
import drjit as _dr
from drjit import ArrayBase, VarType, Exception, Dynamic
from drjit.detail import array_name as _array_name
from sys import modules as _modules
import math as _math
import builtins as _builtins
from functools import wraps as _wraps
from collections.abc import Mapping as _Mapping, \
                            Sequence as _Sequence

# -------------------------------------------------------------------
#                        Type promotion logic
# -------------------------------------------------------------------


def _var_is_drjit(a):
    return isinstance(a, ArrayBase)


def _var_type(a, preferred=VarType.Void):
    '''
    Return the VarType of a given Dr.Jit object or plain Python type. Return
    'preferred' when there is sufficient room for interpretation (e.g. when
    given an 'int').
    '''
    if isinstance(a, ArrayBase):
        return a.Type
    elif isinstance(a, float):
        return VarType.Float32
    elif isinstance(a, bool):
        return VarType.Bool
    elif isinstance(a, int):
        ok = False

        if preferred is not VarType.Void:
            if preferred == VarType.UInt32:
                ok |= a >= 0 and a <= 0xFFFFFFFF
            elif preferred == VarType.Int32:
                ok |= a >= -0x7FFFFFFF and a <= 0x7FFFFFFF
            elif preferred == VarType.UInt64:
                ok |= a >= 0 and a <= 0xFFFFFFFFFFFFFFFF
            elif preferred == VarType.Int64:
                ok |= a >= -0x7FFFFFFFFFFFFFFF and a <= 0x7FFFFFFFFFFFFFFF

        if not ok:
            if a >= 0:
                if a <= 0xFFFFFFFF:
                    preferred = VarType.UInt32
                else:
                    preferred = VarType.UInt64
            else:
                if a >= -0x7FFFFFFF:
                    preferred = VarType.Int32
                else:
                    preferred = VarType.Int64

        return preferred
    elif type(a).__module__ == 'numpy':
        for t in [VarType.Float16, VarType.Float32, VarType.Float64,
                  VarType.Int32, VarType.Int64, VarType.UInt32, VarType.UInt64]:
            if t.NumPy == a.dtype:
                return t
    elif isinstance(a, _Sequence) and not isinstance(a, str):
        return _builtins.max([_var_type(v, preferred) for v in a])
    elif isinstance(a, type(None)) or 'pybind11' in type(type(a)).__name__:
        return VarType.Pointer
    else:
        raise Exception("var_type(): Unsupported type!")


def _var_promote(*args):
    '''
    Given a list of Dr.Jit arrays and scalars, determine the flavor and shape of
    the result array and broadcast/convert everything into this form.
    '''
    n = len(args)
    vt = [None] * n
    base = None
    depth = 0
    diff = False
    shape = []

    for i, a in enumerate(args):
        vt[i] = _var_type(a)
        depth_i = getattr(a, 'Depth', 0)
        diff |= getattr(a, 'IsDiff', False)
        if depth_i > depth:
            base = a
            depth = depth_i
        if _dr.is_tensor_v(a):
            base = a
            shape = a.shape

    if base is None:
        raise Exception("At least one of the input arguments "
                        "must be an Dr.Jit array!")

    for i in range(n):
        j = (i + 1) % n
        if vt[i] != vt[j]:
            vt[i] = _var_type(args[i], vt[j])

    t = type(base)
    vtm = _builtins.max(vt)
    if t.IsDiff != diff or t.Type != vtm:
        t = base.ReplaceScalar(vtm, diff)

    result = list(args)
    for i, a in enumerate(result):
        if type(a) is not t:
            if _dr.is_tensor_v(t):
                try:
                    result[i] = t(result[i], shape)
                except:
                    result[i] = t(result[i])
            else:
                result[i] = t(result[i])

    return result


def _var_promote_mask(a0, a1):
    '''
    Like _var_promote(), but has a special case where 'a1' can be a mask.
    '''
    vt0 = _var_type(a0)
    vt1 = _var_type(a1)
    diff = getattr(a0, 'IsDiff', False) | getattr(a1, 'IsDiff', False)

    if vt0 != vt1:
        vt0 = _var_type(a0, vt1)
        vt1 = _var_type(a1, vt0)

    if vt1 != VarType.Bool:
        vt0 = vt1 = _builtins.max(vt0, vt1)

    base = a0 if getattr(a0, 'Depth', 0) >= getattr(a1, 'Depth', 0) else a1
    t0 = base.ReplaceScalar(vt0, diff)
    t1 = base.ReplaceScalar(vt1, diff)

    if type(a0) is not t0:
        a0 = t0(a0)
    if type(a1) is not t1:
        a1 = t1(a1)

    return a0, a1


def _var_promote_select(a0, a1, a2):
    '''
    Like _var_promote(), but specially adapted to the select() operation
    '''
    vt0 = _var_type(a0)
    vt1 = _var_type(a1)
    vt2 = _var_type(a2)
    diff = getattr(a0, 'IsDiff', False) | \
           getattr(a1, 'IsDiff', False) | \
           getattr(a2, 'IsDiff', False)

    if vt1 != vt2:
        vt1 = _var_type(a1, vt2)
        vt2 = _var_type(a2, vt1)

    if vt0 != VarType.Bool:
        raise Exception("select(): first argument must be a mask!")

    base = a0 if getattr(a0, 'Depth', 0) >= getattr(a1, 'Depth', 0) else a1
    base = base if getattr(base, 'Depth', 0) >= getattr(a2, 'Depth', 0) else a2

    t0 = base.MaskType
    t12 = base.ReplaceScalar(_builtins.max(vt1, vt2), diff)

    if type(a0) is not t0:
        a0 = t0(a0)
    if type(a1) is not t12:
        a1 = t12(a1)
    if type(a2) is not t12:
        a2 = t12(a2)

    return a0, a1, a2


def _replace_scalar(cls, vt, diff=None):
    '''
    Replace the scalar type associated to a Dr.Jit type, specified by a VarType
    '''
    name = _array_name(cls.Prefix, vt, cls.Shape, cls.IsScalar)
    modname = cls.__module__

    if not modname.startswith('drjit.'):
        if cls.IsCUDA:
            modname = "drjit.cuda"
        elif cls.IsLLVM:
            modname = "drjit.llvm"
        elif cls.IsPacket:
            modname = "drjit.packet"
        else:
            modname = "drjit.scalar"

        if cls.IsDiff:
            modname += '.ad'

    if diff is not None:
        is_diff = modname.endswith('.ad')
        if is_diff != diff:
            if diff:
                modname += '.ad'
            else:
                modname = modname[:-3]

    module = _modules.get(modname)
    return getattr(module, name)


ArrayBase.ReplaceScalar = classmethod(_replace_scalar)


# -------------------------------------------------------------------
#                      Miscellaneous operations
# -------------------------------------------------------------------


def shape(arg, /):
    '''
    shape(arg, /)
    Return a tuple describing dimension and shape of the provided Dr.Jit array
    or tensor.

    When the arrays is ragged, the implementation signals a failure by returning
    ``None``. A ragged array has entries of incompatible size, e.g. ``[[1, 2],
    [3, 4, 5]]``. Note that an scalar entries (e.g. ``[[1, 2], [3]]``) are
    acceptable, since broadcasting can effectively convert them to any size.

    The expressions ``drjit.shape(arg)`` and ``arg.shape`` are equivalent.

    Args:
        arg (drjit.ArrayBase): An arbitrary Dr.Jit array or tensor

    Returns:
        tuple | NoneType: A tuple describing the dimension and shape of the
          provided Dr.Jit input array or tensor. When the input array is *ragged*
          (i.e., when it contains components with mismatched sizes), the function
          returns ``None``.
    '''
    if _dr.is_tensor_v(arg):
        return arg.shape

    def _shape_impl(a, i, shape):
        if not isinstance(a, ArrayBase):
            return False

        size = len(a)
        if i < len(shape):
            cur = shape[i]
            maxval = _builtins.max(cur, size)

            if cur != size and size != 1 and cur != 1:
                return False

            shape[i] = maxval
        else:
            shape.append(size)

        if issubclass(a.Value, ArrayBase):
            for j in range(size):
                if not _shape_impl(a[j], i + 1, shape):
                    return False

        return True

    s = []
    if not _shape_impl(arg, 0, s):
        return None
    else:
        return s


def width(arg, /):
    '''
    width(arg, /)
    Return the width of the provided dynamic Dr.Jit array, tensor, or
    :ref:`custom data structure <custom-struct>`.

    The function returns ``1`` if the input variable isn't a Dr.Jit array,
    tensor, or :ref:`custom data structure <custom-struct>`.

    Args:
        arg (drjit.ArrayBase): An arbitrary Dr.Jit array, tensor, or
          :ref:`custom data structure <custom-struct>`

    Returns:
        int: The dynamic width of the provided variable.
    '''
    if _dr.is_array_v(arg):
        if _dr.is_tensor_v(arg):
            return width(arg.array)
        else:
            s = shape(arg)
            if s is None:
                raise Exception('width(): ragged arrays not permitted!')
            return s[-1]
    elif _dr.is_struct_v(arg):
        result = 0
        for k in type(arg).DRJIT_STRUCT.keys():
            result = _builtins.max(result, width(getattr(arg, k)))
        return result
    else:
        return 1


def resize(arg, size):
    '''
    resize(arg, size)
    Resize in-place the provided Dr.Jit array, tensor, or
    :ref:`custom data structure <custom-struct>` to a new size.

    The provided variable must have a size of zero or one originally otherwise
    this function will fail.

    When the provided variable doesn't have a size of 1 and its size exactly
    matches ``size`` the function does nothing. Otherwise, it fails.

    Args:
        arg (drjit.ArrayBase): An arbitrary Dr.Jit array, tensor, or
          :ref:`custom data structure <custom-struct>` to be resized

        size (int): The new size
    '''
    if _dr.depth_v(arg) > 1:
        for i in range(arg.Size):
            resize(arg[i], size)
    elif _dr.is_jit_v(arg):
        arg.resize_(size)
    elif _dr.is_struct_v(arg):
        for k in type(arg).DRJIT_STRUCT.keys():
            resize(getattr(arg, k), size)


def device(value=None):
    '''
    Return the CUDA device ID associated with the current thread. (-1 if CPU)
    '''
    if value is None:
        return _dr.detail.device()
    elif _dr.depth_v(value) > 1:
        return device(value[0])
    elif _dr.is_diff_v(value):
        return device(_dr.detach(value, preserve_type=False))
    elif _dr.is_jit_v(value):
        try:
            return _dr.detail.device(value.index)
        except RuntimeError as e:
            return 0 if _dr.is_cuda_v(value) else -1
    else:
        return -1


# By default, don't print full contents of arrays with more than 20 entries
_print_threshold = 20


def _repr_impl(self, shape, buf, *idx):
    '''
    Implementation detail of op_repr()
    '''
    k = len(shape) - len(idx)
    if k == 0:
        el = idx[0]

        if self.IsQuaternion:
            idx = (3 if el == 0 else (el - 1), *idx[1:])

        value = self
        for k in idx:
            value = value.entry_(k)
        value_str = repr(value)

        if (self.IsComplex or self.IsQuaternion) and el > 0:
            if value_str[0] == '-':
                value_str = '- ' + value_str[1:]
            else:
                value_str = '+ ' + value_str

            value_str += '_ijk'[el]

        buf.write(value_str)
    else:
        size = shape[k - 1]
        buf.write('[')
        i = 0
        while i < size:
            if size > _print_threshold and i == 5:
                buf.write('.. %i skipped ..' % (size - 10))
                i = size - 6
            else:
                _repr_impl(self, shape, buf, i, *idx)

            if i + 1 < size:
                if k == 1:
                    buf.write(' ' if self.IsComplex or self.IsQuaternion
                              else ', ')
                else:
                    buf.write(',\n')
                    buf.write(' ' * (len(idx) + 1))
            i += 1
        buf.write(']')


def print_threshold():
    '''
    Return the maximum number of entries displayed when printing an array
    '''
    return _print_threshold


def set_print_threshold(size):
    '''
    Set the maximum number of entries displayed when printing an array
    '''
    global _print_threshold
    _print_threshold = _builtins.max(size, 11)


def op_repr(self):
    if len(self) == 0:
        return '[]'

    s = shape(self)
    if s is None:
        return "[ragged array]"
    else:
        if self.IsTensor:
            return f"{type(self).__name__}(shape={s})"

        import io
        buf = io.StringIO()
        try:
            self.schedule_()
        except BaseException as e:  # noqa
            return "[backend issue: %s]" % str(e)
        _repr_impl(self, s, buf)
        return buf.getvalue()


def op_bool(self):
    raise Exception(
        "To convert an Dr.Jit array into a boolean value, use a mask reduction "
        "operation such as drjit.all(), drjit.any(), drjit.none(). Special "
        "variants (drjit.all_nested(), etc.) are available for nested arrays.")


def op_len(self):
    return self.Size


# Mainly for testcases: keep track of how often entry() is invoked.
_entry_evals = 0


def op_getitem(self, index):
    global _entry_evals
    if isinstance(index, int):
        size = len(self)
        if size == 1:
            index = 0
        if index < 0:
            index = size + index

        if index >= 0 and index < size:
            _entry_evals += 1
            if self.Depth > 1:
                return self.entry_ref_(index)
            else:
                return self.entry_(index)
        else:
            raise IndexError("%s.__getitem__(): entry %i is out of bounds "
                             "(the array is of size %i)." % (type(self), index, size))

    elif isinstance(index, tuple):
        if self.IsMatrix:
            index = (index[1], index[0], *index[2:])
        for i in index:
            self = op_getitem(self, i)
        return self
    elif isinstance(index, _builtins.slice):
        if not self.Size == Dynamic:
            raise Exception("Indexing via slice is only allowed in the case of "
                            "dynamic arrays")
        indices = tuple(range(len(self)))[index]
        result = _dr.empty(type(self), len(indices))
        for i in range(len(indices)):
            result[i] = op_getitem(self, indices[i])
        return result
    elif _dr.is_mask_v(index):
        return type(self)(self)
    else:
        raise Exception("Invalid array index! (must be an integer or a tuple "
                        "of integers!)")


def op_setitem(self, index, value):
    if isinstance(index, int):
        size = len(self)
        if index < 0:
            index = size + index
        if index >= 0 and index < size:
            global _entry_evals
            _entry_evals += 1
            if not type(value) is self.Value:
                self.set_entry_(index, self.Value(value))
            else:
                self.set_entry_(index, value)
        else:
            raise IndexError("Tried to write to array index %i, which "
                             "exceeds its size (%i)!" % (index, size))
    elif isinstance(index, tuple):
        if len(index) > 1:
            if self.IsMatrix:
                index = (index[1], index[0], *index[2:])
            if isinstance(index[0], _builtins.slice):
                indices = tuple(range(len(self)))[index[0]]
                for i in range(len(indices)):
                    value2 = op_getitem(self, indices[i])
                    op_setitem(value2, index[1:], value)
                    op_setitem(self, indices[i], value2)
            else:
                value2 = op_getitem(self, index[0])
                op_setitem(value2, index[1:], value)
                op_setitem(self, index[0], value2)
        else:
            op_setitem(self, index[0], value)
    elif _dr.is_mask_v(index):
        self.assign(_dr.select(index, value, self))
    elif isinstance(index, _builtins.slice):
        indices = tuple(range(len(self)))[index]
        for i in range(len(indices)):
            if isinstance(value, (float, int, bool)):
                op_setitem(self, indices[i], value)
            else:
                op_setitem(self, indices[i], value[i])
    else:
        raise Exception("Invalid array index! (must be an integer or a tuple "
                        "of integers!)")
    return self


def reinterpret_array_v(dtype, value):
    '''
    Reinterpret the provided Dr.Jit array/tensor into a specified type.

    Args:
        dtype (type): Target type for the reinterpretation.

        value (object): Dr.Jit array or tensor to reinterpret.

    Returns:
        object: Result of the conversion as described above.
    '''
    assert isinstance(dtype, type)

    def reinterpret_array(dtype, value, vt_target, vt_value):
        if issubclass(dtype, ArrayBase):
            if hasattr(dtype, "reinterpret_array_"):
                return dtype.reinterpret_array_(value)
            else:
                result = dtype()
                if result.Size == Dynamic:
                    result.init_(len(value))

                for i in range(len(value)):
                    result[i] = reinterpret_array(dtype.Value, value[i],
                                                  dtype.Type, value.Type)

                return result
        else:
            return _dr.detail.reinterpret_scalar(value, vt_value, vt_target)

    return reinterpret_array(dtype, value, _dr.VarType.Void,  _dr.VarType.Void)


