#                  Higher-level utility functions
# -------------------------------------------------------------------

def allclose(a, b, rtol=1e-5, atol=1e-8, equal_nan=False):
    r'''
    Returns ``True`` if two arrays are element-wise equal within a given error
    tolerance.

    The function considers both absolute and relative error thresholds. Specifically
    **a** and **b** are considered equal if all elements satisfy

    .. math::
        |a - b| \le |b| \cdot \mathrm{rtol} + \mathrm{atol}.

    Args:
        a (object): A Dr.Jit array or other kind of numeric sequence type.

        b (object): A Dr.Jit array or other kind of numeric sequence type.

        rtol (float): A relative error threshold. The default is :math:`10^{-5}`.

        atol (float): An absolute error threshold. The default is :math:`10^{-8}`.

        equal_nan (bool): If **a** and **b** *both* contain a *NaN* (Not a Number) entry,
                          should they be considered equal? The default is ``False``.

    Returns:
        bool: The result of the comparison.
    '''
    if _dr.is_array_v(a) or _dr.is_array_v(b):
        # No derivative tracking in the following
        a, b = _dr.detach(a), _dr.detach(b)

        if _dr.is_array_v(a) and not _dr.is_float_v(a):
            a, _ = _var_promote(a, 1.0)
        if _dr.is_array_v(b) and not _dr.is_float_v(b):
            b, _ = _var_promote(b, 1.0)

        if type(a) is not type(b):
            a, b = _var_promote(a, b)

        diff = abs(a - b)
        shape = 1
        if _dr.is_tensor_v(diff):
            shape = diff.shape
        cond = diff <= abs(b) * rtol + _dr.full(type(diff), atol, shape)
        if _dr.is_float_v(a):
            cond |= _dr.eq(a, b)  # plus/minus infinity

        if equal_nan:
            cond |= _dr.isnan(a) & _dr.isnan(b)

        return _dr.all_nested(cond)

    def safe_len(x):
        try:
            return len(x)
        except TypeError:
            return 0

    def safe_getitem(x, len_x, i):
        if len_x == 0:
            return x
        elif len_x == 1:
            return x[0]
        else:
            return x[i]

    len_a, len_b = safe_len(a), safe_len(b)
    len_ab = _builtins.max(len_a, len_b)

    if len_a != len_ab and len_a > 1 or \
       len_b != len_ab and len_b > 1:
        raise RuntimeError('drjit.allclose(): incompatible sizes '
                           '(%i and %i)!' % (len_a, len_b))
    elif len_ab == 0:
        if equal_nan and _math.isnan(a) and _math.isnan(b):
            return True
        return _dr.abs(a - b) <= _dr.abs(b) * rtol + atol
    else:
        for i in range(len_ab):
            ia = safe_getitem(a, len_a, i)
            ib = safe_getitem(b, len_b, i)
            if not allclose(ia, ib, rtol, atol, equal_nan):
                return False
        return True


def printf_async(fmt, *args, active=True):
    '''
    Print the specified variable contents from the kernel asynchronously.

    This function inserts a print statement directly into the kernel being
    generated. Note that this may produce a very large volume of output,
    and a nonzero ``active`` parameter can be supplied to suppress it based
    on condition.

    Args:
        fmt (str): The string to be printed. It might contain *format specifiers*
          (e.g. subsequences beginning with %)

        *args (tuple): Additional array arguments to be formatted and inserted
          in the printed string replacing their respective specifiers.

        active (bool | drjit.ArrayBase): Mask array to suppress printing specific
          elements in the supplied additional arrays.
    '''
    indices = []
    is_cuda, is_llvm = _dr.is_cuda_v(active), _dr.is_llvm_v(active)

    for a in args:
        cuda, llvm = _dr.is_cuda_v(a), _dr.is_llvm_v(a)
        if not (cuda or llvm) or _dr.depth_v(a) != 1 or _dr.is_mask_v(a):
            raise Exception("printf_async(): array argument of type '%s' not "
                            "supported (must be a depth-1 JIT (LLVM/CUDA) array, "
                            "and cannot be a mask)" % type(a).__name__)
        indices.append(a.index)
        is_cuda |= cuda
        is_llvm |= llvm

    if is_cuda == is_llvm:
        raise Exception("printf_async(): invalid input: must specify LLVM or CUDA arrays.")

    active = _dr.cuda.Bool(active) if is_cuda else _dr.llvm.Bool(active)
    _dr.detail.printf_async(is_cuda, active.index, fmt, indices)


# -------------------------------------------------------------------
#               Context manager for setting JIT flags
# -------------------------------------------------------------------

class scoped_set_flag:
    def __init__(self, flag, value):
        self.flag = flag
        self.value = value

    def __enter__(self):
        self.backup = _dr.flag(self.flag)
        _dr.set_flag(self.flag, self.value)

    def __exit__(self, exc_type, exc_val, exc_tb):
        _dr.set_flag(self.flag, self.backup)

# -------------------------------------------------------------------
#                        Enabling/disabling AD
# -------------------------------------------------------------------

class _DummyContextManager:
    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc_val, exc_tb):
        pass

class _ADContextManager:
    def __init__(self, scope_type, array_type, array_indices):
        self.scope_type = scope_type
        self.array_type = array_type
        self.array_indices = array_indices

    def __enter__(self):
        if self.array_type is not None:
            self.array_type.scope_enter_(self.scope_type, self.array_indices)
        else:
            if hasattr(_dr, 'cuda'):
                _dr.cuda.ad.Float32.scope_enter_(self.scope_type, self.array_indices)
                _dr.cuda.ad.Float64.scope_enter_(self.scope_type, self.array_indices)
            if hasattr(_dr, 'llvm'):
                _dr.llvm.ad.Float32.scope_enter_(self.scope_type, self.array_indices)
                _dr.llvm.ad.Float64.scope_enter_(self.scope_type, self.array_indices)

    def __exit__(self, exc_type, exc_val, exc_tb):
        success = exc_type is None

        if self.array_type is not None:
            self.array_type.scope_leave_(success)
        else:
            if hasattr(_dr, 'cuda'):
                _dr.cuda.ad.Float32.scope_leave_(success)
                _dr.cuda.ad.Float64.scope_leave_(success)
            if hasattr(_dr, 'llvm'):
                _dr.llvm.ad.Float32.scope_leave_(success)
                _dr.llvm.ad.Float64.scope_leave_(success)


def suspend_grad(*args, when=True):
    '''
    suspend_grad(*args, when = True)
    Context manager for temporally suspending derivative tracking.

    Dr.Jit's AD layer keeps track of a set of variables for which derivative
    tracking is currently enabled. Using this context manager is it possible to
    define a scope in which variables will be subtracted from that set, thereby
    controlling what derivative terms shouldn't be generated in that scope.

    The variables to be subtracted from the current set of enabled variables can be
    provided as function arguments. If none are provided, the scope defined by this
    context manager will temporally disable all derivative tracking.

    .. code-block::

        a = dr.llvm.ad.Float(1.0)
        b = dr.llvm.ad.Float(2.0)
        dr.enable_grad(a, b)

        with suspend_grad(): # suspend all derivative tracking
            c = a + b

        assert not dr.grad_enabled(c)

        with suspend_grad(a): # only suspend derivative tracking on `a`
            d = 2.0 * a
            e = 4.0 * b

        assert not dr.grad_enabled(d)
        assert dr.grad_enabled(e)

    In a scope where derivative tracking is completely suspended, the AD layer will
    ignore any attempt to enable gradient tracking on a variable:

    .. code-block::

        a = dr.llvm.ad.Float(1.0)

        with suspend_grad():
            dr.enable_grad(a) # <-- ignored
            assert not dr.grad_enabled(a)

        assert not dr.grad_enabled(a)

    The optional ``when`` boolean keyword argument can be defined to specifed a
    condition determining whether to suspend the tracking of derivatives or not.

    .. code-block::

        a = dr.llvm.ad.Float(1.0)
        dr.enable_grad(a)

        cond = condition()

        with suspend_grad(when=cond):
            b = 4.0 * a

        assert dr.grad_enabled(b) == not cond

    Args:
        *args (tuple): A variable-length list of differentiable Dr.Jit array
          instances, :ref:`custom data structures <custom-struct>`, sequences, or
          mappings. The function will recursively traverse data structures to
          discover all Dr.Jit arrays.

        when (bool): An optional Python boolean determining whether to suspend
          derivative tracking.
    '''
    if not when or (not hasattr(_dr.detail, 'ADScope')):
        return _DummyContextManager()

    array_indices = []
    _dr.detail.diff_vars(args, array_indices, check_grad_enabled=False)
    if len(args) > 0 and len(array_indices) == 0:
        array_indices = [0]
    return _ADContextManager(_dr.detail.ADScope.Suspend, _dr.leaf_array_t(args), array_indices)


def resume_grad(*args, when=True):
    '''
    resume_grad(*args, when = True)
    Context manager for temporally resume derivative tracking.

    Dr.Jit's AD layer keeps track of a set of variables for which derivative
    tracking is currently enabled. Using this context manager is it possible to
    define a scope in which variables will be added to that set, thereby controlling
    what derivative terms should be generated in that scope.

    The variables to be added to the current set of enabled variables can be
    provided as function arguments. If none are provided, the scope defined by this
    context manager will temporally resume derivative tracking for all variables.

    .. code-block::

        a = dr.llvm.ad.Float(1.0)
        b = dr.llvm.ad.Float(2.0)
        dr.enable_grad(a, b)

        with suspend_grad():
            c = a + b

            with resume_grad():
                d = a + b

            with resume_grad(a):
                e = 2.0 * a
                f = 4.0 * b

        assert not dr.grad_enabled(c)
        assert dr.grad_enabled(d)
        assert dr.grad_enabled(e)
        assert not dr.grad_enabled(f)

    The optional ``when`` boolean keyword argument can be defined to specifed a
    condition determining whether to resume the tracking of derivatives or not.

    .. code-block::

        a = dr.llvm.ad.Float(1.0)
        dr.enable_grad(a)

        cond = condition()

        with suspend_grad():
            with resume_grad(when=cond):
                b = 4.0 * a

        assert dr.grad_enabled(b) == cond

    Args:
        *args (tuple): A variable-length list of differentiable Dr.Jit array
          instances, :ref:`custom data structures <custom-struct>`, sequences, or
          mappings. The function will recursively traverse data structures to
          discover all Dr.Jit arrays.

        when (bool): An optional Python boolean determining whether to resume
          derivative tracking.
    '''
    if not when or (not hasattr(_dr.detail, 'ADScope')):
        return _DummyContextManager()

    array_indices = []
    _dr.detail.diff_vars(args, array_indices, check_grad_enabled=False)
    if len(args) > 0 and len(array_indices) == 0:
        array_indices = [0]
    return _ADContextManager(_dr.detail.ADScope.Resume, _dr.leaf_array_t(args), array_indices)


def isolate_grad(when=True):
    '''
    Context manager to temporarily isolate outside world from AD traversals.

    Dr.Jit provides isolation boundaries to postpone AD traversals steps leaving a
    specific scope. For instance this function is used internally to implement
    differentiable loops and polymorphic calls.
    '''
    if not when or (not hasattr(_dr.detail, 'ADScope')):
        return _DummyContextManager()
    return _ADContextManager(_dr.detail.ADScope.Isolate, None, [])


# -------------------------------------------------------------------
#             Automatic differentation of custom functions
# -------------------------------------------------------------------

class CustomOp:
    '''
    Base class to implement custom differentiable operations.

    Dr.Jit can compute derivatives of builtin operations in both forward and reverse
    mode. In some cases, it may be useful or even necessary to tell Dr.Jit how a
    particular operation should be differentiated.

    This can be achieved by extending this class, overwriting callback functions
    that will later be invoked when the AD backend traverses the associated node in
    the computation graph. This class also provides a convenient way of stashing
    temporary results during the original function evaluation that can be accessed
    later on as part of forward or reverse-mode differentiation.

    Look at the section on :ref:`AD custom operations <custom-op>` for more detailed
    information.

    A class that inherits from this class should override a few methods as done in
    the code snippet below. :py:func:`dr.custom` can then be used to evaluate the
    custom operation and properly attach it to the AD graph.

    .. code-block::

        class MyCustomOp(dr.CustomOp):
            def eval(self, *args):
                # .. evaluate operation ..

            def forward(self):
                # .. compute forward-mode derivatives ..

            def backward(self):
                # .. compute backward-mode derivatives ..

            def name(self):
                return "MyCustomOp[]"

        dr.custom(MyCustomOp, *args)
    '''
    def __init__(self):
        self._implicit_in = []
        self._implicit_out = []

    def eval(self, *args):
        '''
        eval(self, *args) -> object
        Evaluate the custom function in primal mode.

        The inputs will be detached from the AD graph, and the output *must* also be
        detached.

        .. danger::

            This method must be overriden, no default implementation provided.
        '''
        raise Exception("CustomOp.eval(): not implemented")

    def forward(self):
        '''
        Evaluated forward-mode derivatives.

        .. danger::

            This method must be overriden, no default implementation provided.
        '''
        raise Exception("CustomOp.forward(): not implemented")

    def backward(self):
        '''
        Evaluated backward-mode derivatives.

        .. danger::

            This method must be overriden, no default implementation provided.
        '''
        raise Exception("CustomOp.backward(): not implemented")

    def grad_out(self):
        '''
        Access the gradient associated with the output argument (backward mode AD).

        Returns:
            object: the gradient value associated with the output argument.
        '''
        return _dr.grad(self.output)

    def set_grad_out(self, value):
        '''
        Accumulate a gradient value into the output argument (forward mode AD).

        Args:
            value (object): gradient value to accumulate.
        '''
        _dr.accum_grad(self.output, value)

    def grad_in(self, name):
        '''
        Access the gradient associated with the input argument ``name`` (fwd. mode AD).

        Args:
            name (str): name associated to an input variable (e.g. keyword argument).

        Returns:
            object: the gradient value associated with the input argument.
        '''
        if name not in self.inputs:
            raise Exception("CustomOp.grad_in(): Could not find "
                            "input argument named \"%s\"!" % name)
        return _dr.grad(self.inputs[name])

    def set_grad_in(self, name, value):
        '''
        Accumulate a gradient value into an input argument (backward mode AD).

        Args:
            name (str): name associated to the input variable (e.g. keyword argument).
            value (object): gradient value to accumulate.
        '''
        if name not in self.inputs:
            raise Exception("CustomOp.set_grad_in(): Could not find "
                            "input argument named \"%s\"!" % name)
        _dr.accum_grad(self.inputs[name], value)

    def add_input(self, value):
        '''
        Register an implicit input dependency of the operation on an AD variable.

        This function should be called by the ``eval()`` implementation when an
        operation has a differentiable dependence on an input that is not an
        input argument (e.g. a private instance variable).

        Args:
            value (object): variable this operation depends on implicitly.
        '''
        _dr.detail.diff_vars(value, self._implicit_in)

    def add_output(self, value):
        '''
        Register an implicit output dependency of the operation on an AD variable.

        This function should be called by the \ref eval() implementation when an
        operation has a differentiable dependence on an output that is not an
        return value of the operation (e.g. a private instance variable).

        Args:
            value (object): variable this operation depends on implicitly.
        '''
        _dr.detail.diff_vars(value, self._implicit_out)

    def __del__(self):
        @_dr.detail.traverse()
        def ad_clear(arg):
            if _dr.is_diff_v(arg):
                arg.set_index_ad_(0)
        ad_clear(getattr(self, 'output', None))

    def name(self):
        '''
        Return a descriptive name of the ``CustomOp`` instance.

        The name returned by this method is used in the GraphViz output.

        If not overriden, this method returns ``"CustomOp[unnamed]"``.
        '''
        return "CustomOp[unnamed]"


def custom(cls, *args, **kwargs):
    '''
    Evaluate a custom differentiable operation (see :py:class:`CustomOp`).

    Look at the section on :ref:`AD custom operations <custom-op>` for more detailed
    information.
    '''
    # Clear primal values of a differentiable array
    @_dr.detail.traverse(traverse_tensor=False)
    def clear_primal(arg, dec_ref):
        if _dr.is_diff_v(arg) and _dr.is_float_v(arg):
            tp = type(arg)
            if _dr.is_tensor_v(tp):
                zeros = _dr.zeros(_dr.detached_t(tp.Array), prod(arg.shape))
                value = tp.Array.create_(arg.array.index_ad, zeros)
                result = tp(value, arg.shape)
            else:
                result = value = tp.create_(arg.index_ad, _dr.detached_t(tp)())
            if dec_ref:
                value.ad_dec_ref_()
            return result
        else:
            return arg

    # Cast input values into differentiable types
    @_dr.detail.traverse(traverse_tensor=False)
    def to_diff_array(o):
        return _dr.diff_array_t(o)(o)

    inst = cls()

    # Convert args to kwargs
    kwargs.update(zip(inst.eval.__code__.co_varnames[1:], args))

    # Check whether customop has variable number of arguments (*args)
    eval_args = len(kwargs) == 1 and list(kwargs)[0] == 'args'

    if eval_args:
        output = inst.eval(*_dr.detach(kwargs['args']))
    else:
        output = inst.eval(**{ k: _dr.detach(v) for k, v in kwargs.items() })
    if _dr.grad_enabled(output):
        raise RuntimeError("drjit.custom(): the return value of CustomOp.eval() "
                           "should not be attached to the AD graph!")

    diff_vars_in = inst._implicit_in
    _dr.detail.diff_vars(kwargs, diff_vars_in)

    if len(diff_vars_in) > 0:
        output = to_diff_array(output)
        Type = _dr.leaf_array_t(output)
        tmp_in, tmp_out = Type(), Type()
        _dr.enable_grad(tmp_in, tmp_out, output)

        inst.inputs = clear_primal(kwargs, dec_ref=False)
        inst.output = clear_primal(output, dec_ref=True)

        diff_vars_out = inst._implicit_out
        _dr.detail.diff_vars(inst.output, diff_vars_out)

        if len(diff_vars_out) == 0:
            return output # Not relevant for AD after all..

        if len(diff_vars_in) > 1:
            _dr.set_label(tmp_in, inst.name() + "_in")
            for index in diff_vars_in:
                Type.ad_add_edge_(index, tmp_in.index_ad)

        if len(diff_vars_out) > 1:
            _dr.set_label(tmp_out, inst.name() + "_out")
            for index in diff_vars_out:
                Type.ad_add_edge_(tmp_out.index_ad, index)

        Type.ad_add_edge_(
            diff_vars_in[0]  if len(diff_vars_in)  == 1 else tmp_in.index_ad,
            diff_vars_out[0] if len(diff_vars_out) == 1 else tmp_out.index_ad,
            inst
        )

        inst._implicit_in = []
        inst._implicit_out = []

    return output


def wrap_ad(source: str, target: str):
    '''
    Function decorator that wraps the excecution of a function using a different
    AD framework to ensure that gradients can flow seamlessly between both
    frameworks.

    Using this decorator it is possible to mix AD-aware computation between two
    AD frameworks (e.g. Dr.Jit and PyTorch). The wrapped function's arguments
    will be casted to the tensor types corresponding to the ``target`` framework.
    Similarily, the return values will be casted to the tensor types corresponding
    to the ``source`` framework.

    The decorated function can take an arbitrary number of arguments and have any
    number of return values.

    Currently only the following combination of frameworks are supported:

    .. list-table::
        :header-rows: 1

        * - ``source``
          - ``target``
          - Forward AD
          - Backward AD
        * - ``drjit``
          - ``torch``
          - ❌
          - ✔️
        * - ``torch``
          - ``drjit``
          - ❌
          - ✔️

    The example below shows how to wrap a Dr.Jit function in a PyTorch script:

    .. code-block:: python

        # Start with a PyTorch tensor
        a = torch.tensor([1.0, 2.0, 3.0], requires_grad=True)

        # Some PyTorch arithmetic
        b = torch.sin(a)

        # Wrap a function performing some arithmetic using Dr.Jit
        @dr.wrap_ad(source='torch', target='drjit')
        def dr_func(x):
            return dr.cos(x) + dr.power(x, 2)

        # Excecute the wrapped function (returns a PyTorch tensor)
        c = dr_func(b)

        # Some more PyTorch arithmetic
        d = torch.tan(c)

        # Propagate gradients to variable a (through PyTorch -> Dr.Jit -> PyTorch)
        d.sum().backward()

        # Inspect the resulting gradients
        print(a.grad)

    Similarily the following example shows how to wrap PyTorch code into a
    Dr.Jit script:

    .. code-block:: python

        # Start with a Dr.Jit tensor
        a = dr.llvm.ad.TensorXf([1, 2, 3], shape=[3])
        dr.enable_grad(a)

        # Some Dr.Jit arithmetic
        b = dr.sin(a)

        # Wrap a function performing some arithmetic using PyTorch
        @dr.wrap_ad(source='drjit', target='torch')
        def torch_func(x):
            return torch.cos(x) + torch.sin(x)

        # Excecute the wrapped function (returns a Dr.Jit tensor)
        c = torch_func(b)

        # Some more Dr.Jit arithmetic
        d = dr.tan(c)

        # Propagate gradients to variable a (through Dr.Jit -> PyTorch -> Dr.Jit)
        dr.backward(d)

        # Inspect the resulting gradients
        print(dr.grad(a))

    .. danger::

        Forward-mode AD isn't currently supported by this operation.

    Args:
        source (str | module): The AD framework used outside of the wrapped function.
        target (str | module): The AD framework used within the wrapped function.

    Returns:
        The decorated function.
    '''
    # Get module names if source and target are not already strings
    source = source.__name__ if not isinstance(source, str) else source
    target = target.__name__ if not isinstance(target, str) else target

    if not 'drjit' in [source, target]:
        raise TypeError('wrap_ad(): invalid combination of frameworks, '
                        'expected one to be drjit!', source, target)

    def wrapper(func: Callable):
        @_wraps(func)
        def f(*args, **kwargs):
            if 'torch' in [source, target]:
                import torch as _torch

            # Return whether the input argument is a PyTorch tensor
            def is_torch_tensor(a):
                return getattr(a, '__module__', None) == 'torch' \
                       and type(a).__name__ == 'Tensor'

            # Casting routing from Dr.Jit tensors to PyTorch tensors
            def drjit_to_torch(a, enable_grad = False):
                if isinstance(a, _Sequence) and not isinstance(a, str):
                    return tuple(drjit_to_torch(b, enable_grad) for b in a)
                elif isinstance(a, _Mapping):
                    return {k: drjit_to_torch(v, enable_grad) for k, v in a.items()}
                elif _dr.is_array_v(a) and _dr.is_tensor_v(a):
                    b = a.torch()
                    b.requires_grad = _dr.grad_enabled(a) or (enable_grad and _dr.is_diff_v(a))
                    return b
                elif _dr.is_diff_v(a) and a.IsFloat:
                    raise TypeError("wrap_ad(): differential input arguments "
                                    "should be Dr.Jit tensor!")
                else:
                    return a

            # Casting routing from PyTorch tensors to Dr.Jit tensors
            def torch_to_drjit(a):
                if isinstance(a, _Sequence) and not isinstance(a, str):
                    return tuple(torch_to_drjit(b) for b in a)
                elif isinstance(a, _Mapping):
                    return {k: torch_to_drjit(v) for k, v in a.items()}
                elif is_torch_tensor(a):
                    dtype_str = {
                        _torch.float:   'TensorXf',
                        _torch.float32: 'TensorXf',
                        _torch.float64: 'TensorXf64',
                        _torch.int32:   'TensorXi',
                        _torch.int:     'TensorXi',
                        _torch.int64:   'TensorXi64',
                        _torch.long:    'TensorXi64',
                    }[a.dtype]
                    device = 'cuda' if a.is_cuda else 'llvm'
                    m = getattr(getattr(_dr, device),'ad')
                    return getattr(m, dtype_str)(a)
                else:
                    return a

            # Ensure gradient tensors in `a` have same shape as tensors in `b` (handles dim==0 case)
            def torch_ensure_grad_shape(a, b):
                if isinstance(a, _Sequence) and not isinstance(a, str):
                    return tuple(torch_ensure_grad_shape(a[i], b[i]) for i in range(len(a)))
                elif isinstance(a, _Mapping):
                    return {k: torch_ensure_grad_shape(v, b[k]) for k, v in a.items()}
                elif is_torch_tensor(a) and a.dtype in [_torch.float, _torch.float32, _torch.float64]:
                    return a.reshape(b.shape)
                else:
                    return a

            # Construct the full tuple of positional arguments
            args = _dr.detail.get_args_values(func, *args, **kwargs)

            if source == 'torch':
                class ToDrJit(_torch.autograd.Function):
                    @staticmethod
                    def forward(ctx, *args):
                        ctx.args = args
                        ctx.args_drjit = torch_to_drjit(args)
                        _dr.enable_grad(ctx.args_drjit)
                        res = func(*ctx.args_drjit)
                        ctx.res_drjit = (res,) if not isinstance(res, tuple) else res
                        return drjit_to_torch(res)

                    @staticmethod
                    @_torch.autograd.function.once_differentiable
                    def backward(ctx, *grad_output):
                        _dr.set_grad(ctx.res_drjit, grad_output)
                        _dr.enqueue(_dr.ADMode.Backward, ctx.res_drjit)
                        _dr.traverse(ctx.res_drjit, _dr.ADMode.Backward)
                        args_grad = drjit_to_torch(_dr.grad(ctx.args_drjit))
                        args_grad = torch_ensure_grad_shape(args_grad, ctx.args)
                        del ctx.res_drjit, ctx.args_drjit
                        return args_grad

                return ToDrJit.apply(*args)

            if target == 'torch':
                class ToTorch(_dr.CustomOp):
                    def eval(self, *args):
                        self.args = args
                        self.args_torch = drjit_to_torch(args, enable_grad=True)
                        self.res_torch = func(*self.args_torch)
                        return torch_to_drjit(self.res_torch)

                    def forward(self):
                        raise TypeError("warp_ad(): forward-mode AD is not supported!")

                    def backward(self):
                        grad_out_torch = drjit_to_torch(self.grad_out())
                        grad_out_torch = torch_ensure_grad_shape(grad_out_torch, self.res_torch)
                        def flatten(values):
                            """Flatten structure in a consistent arbitrary order"""
                            result = []
                            def traverse(values):
                                if isinstance(values, _Sequence):
                                    for v in values:
                                        traverse(v)
                                elif isinstance(values, _Mapping):
                                    for _, v in sorted(values.items(), key=lambda item: item[0]):
                                        traverse(v)
                                else:
                                    result.append(values)
                            traverse(values)

                            # Single item should not be wrapped into a list
                            if not isinstance(values, _Sequence) and not isinstance(values, _Mapping):
                                result = result[0]

                            return result

                        _torch.autograd.backward(flatten(self.res_torch), flatten(grad_out_torch))

                        def get_grads(args):
                            if isinstance(args, _Sequence) and not isinstance(args, str):
                                return tuple(get_grads(b) for b in args)
                            elif isinstance(args, _Mapping):
                                return {k: get_grads(v) for k, v in args.items()}
                            elif is_torch_tensor(args):
                                return getattr(args, 'grad', None)
                            else:
                                return None

                        args_grad_torch = get_grads(self.args_torch)
                        args_grad = torch_to_drjit(args_grad_torch)
                        self.set_grad_in('args', args_grad)

                return _dr.custom(ToTorch, args)

        return f

    return wrapper


def graphviz_ad(as_str=False):
    '''
    Assembles a graphviz diagram for the computational graph trace by the AD system.

    Args:
        as_str (bool): whether the function should return the graphviz object as
            a string representation or not.

    Returns:
        object: the graphviz obj (or its string representation).
    '''
    s = _dr.detail.graphviz_ad()

    if as_str:
        return s

    try:
        from graphviz import Source
        return Source(s)
    except ImportError:
        raise Exception('The "graphviz" Python package not available! Install '
                        'via "python -m pip install graphviz". Alternatively, '
                        'you can call drjit.graphviz_ad(as_str=True) to obtain '
                        'a string representation.')

def get_cmake_dir():
    from os import path
    file_dir = path.abspath(path.dirname(__file__))
    cmake_path = path.join(file_dir, "share", "cmake", "drjit")
    if not path.exists(cmake_path):
        raise ImportError("Cannot find Dr.Jit CMake directory")
    return cmake_path

# -------------------------------------------------------------------
#             Function dispatch and polymorphism routines
# -------------------------------------------------------------------

def switch(indices, funcs, *args):
    """
    Dispatches a call to one of the given functions based on the given indices.

    .. code-block:: python

        def f1(x):
             return x * 10

        def f2(x):
             return x * 100

        arg = dr.llvm.Float([1.0, 2.0, 3.0, 4.0])
        indices = dr.llvm.UInt32([0, 1, 1, 0])

        res = dr.switch(indices, [f1, f2], arg)

        # [10.0, 200.0, 300.0, 40.0]

    Args:
        indices (drjit.ArrayBase): a list of indices to choose the functions
        funcs (list): a list of functions to dispatch based on ``indices``
        args (tuple): the arguments to pass to the functions

    Returns:
        object: the result of the function call dispatched based on the indices
    """

    if not _dr.is_unsigned_v(indices):
        raise Exception("switch(): expect indices to be an integer array!")

    if not isinstance(funcs, list):
        raise Exception("switch(): expect funcs to be a list of functions!")

    for f in funcs:
        if f is not None and not callable(f):
            raise Exception("switch(): expect funcs to be a list of functions!")

    Type = _dr.float32_array_t(indices)
    Mask = _dr.mask_t(indices)
    mod = _modules.get(Type.__module__)

    # Dr.Jit expects callable indices to start at 1
    indices = 1 + indices

    # Extract and apply (optional) mask from last argument
    if isinstance(args[-1], Mask):
        indices = _dr.select(args[-1], indices, 0)
        # Set the active mask to True
        args = tuple(a if (i+1) < len(args) else Mask(True) for i, a in enumerate(args))

    if not _dr.flag(_dr.JitFlag.VCallRecord):
        @_dr.detail.traverse()
        def gather_helper(src, idx):
            return _dr.gather(type(src), src, idx)

        @_dr.detail.traverse()
        def zeros_helper(arg):
            return _dr.zeros(type(arg), _dr.width(indices))

        @_dr.detail.traverse()
        def scatter_helper(dst, src, idx):
            _dr.scatter(dst, src, idx)

        return mod.switch_reduce_(indices, funcs, gather_helper,
                                  zeros_helper, scatter_helper, *args)

    if not _dr.is_diff_v(indices):
        return mod.switch_record_(indices, funcs, *args)
    else:
        @_dr.detail.traverse()
        def ad_copy(arg):
            return arg.copy_() if _dr.is_diff_v(arg) else arg

        class ADCopyWrapper:
            def __init__(self, func):
                self.func = func

            def __call__(self, *args, **kwargs):
                return ad_copy(self.func(*args, **kwargs))

        funcs = [
            ADCopyWrapper(func) if func is not None else None for func in funcs
        ]

        class DiffSwitch(_dr.CustomOp):
            def eval(self, indices, funcs, args):
                self.indices = indices
                self.funcs = funcs
                self.args = args
                implicit_snapshot = Type.ad_implicit_()
                res = mod.switch_record_(self.indices, self.funcs, *self.args)
                self._implicit_in = Type.ad_extract_implicit_(implicit_snapshot)
                for i in self._implicit_in:
                    Type.ad_inc_ref_(i)
                return _dr.detach(res)

            def forward(self):
                def generate(func):
                    def fwd(*args):
                        # Prepare arguments
                        args_value, args_grad = zip(*args)
                        args_value = ad_copy(args_value)
                        _dr.enable_grad(args_value)
                        implicit_snapshot = Type.ad_implicit_()
                        # Call function
                        result = func(*args_value)
                        # Propagate gradients from arguments to result
                        _dr.set_grad(args_value, args_grad)
                        _dr.enqueue(_dr.ADMode.Forward, args_value)
                        Type.ad_enqueue_implicit_(implicit_snapshot)
                        _dr.traverse(Type, _dr.ADMode.Forward)
                        Type.ad_dequeue_implicit_(implicit_snapshot)
                        # Return result gradients
                        return _dr.grad(result, preserve_type=True)

                    return fwd

                funcs_fwd = [generate(func) for func in self.funcs]
                args_value_grad = tuple(zip(self.args, self.grad_in('args') ))
                grad_out = mod.switch_record_(self.indices, funcs_fwd, *args_value_grad)
                self.set_grad_out(grad_out)

            def backward(self):
                def generate(func):
                    def bwd(grad_out, *args):
                        # Prepare arguments
                        args = ad_copy(args)
                        _dr.enable_grad(args)
                        # Call function
                        result = func(*args)
                        # Propagate gradients from result to arguments
                        _dr.set_grad(result, grad_out)
                        _dr.enqueue(_dr.ADMode.Backward, result)
                        _dr.traverse(Type, _dr.ADMode.Backward)
                        # Return arguments gradients
                        return _dr.grad(args, preserve_type=True)

                    return bwd

                funcs_bwd = [generate(func) for func in self.funcs]
                grad_in = mod.switch_record_(self.indices, funcs_bwd, self.grad_out(), *self.args)
                self.set_grad_in('args', grad_in)

        return _dr.custom(DiffSwitch, indices, funcs, args)


def dispatch(instances, func, *args):
    """
    Dispatches a call to the given function on an array of instances of a class
    registered to the Dr.Jit registry. The provided function is assumed to take
    at least one argument that will represent the individual instance of the
    class this function is recorded on.

    This routine can be used to perform dynamic dispatch to Python methods of
    instances. The code generation underlying Dr.Jit will transform arbitrary
    sequences of such method calls into unified functions in the generated code.
    In other words, a single dispatch call that calls two methods is potentially
    significantly faster than two separate dispatches.

    .. code-block:: python

        pointers = ... # Dr.Jit pointer array type

        def func(self, arg):
            v = self.foo() # call foo() on a single instance at a time
            return v + arg

        arg = dr.llvm.Float([1.0, 2.0, 3.0, 4.0])

        res = dr.dispatch(pointers, func, arg)

    Args:
        instances (drjit.ArrayBase): array of pointers to instances to dispatch
                                     the given function on.
        func (dict): function to dispatch on all instances.
        args (tuple): the arguments to pass to the function.

    Returns:
        object: the result of the function evaluated for the given instances.
    """
    Type = type(instances)

    if not _dr.is_jit_v(Type) or _dr.detail.VAR_TYPE_NAME[Type.Type] != 'Pointer':
        raise Exception('dispatch(): instances should be an array of pointers!')

    if not isinstance(func, type(lambda:0)):
        raise Exception('dispatch(): func should be function!')

    # Generate functions for all instances of Type
    def generate(inst):
        return (lambda *args: func(inst, *args)) if inst else None
    n_inst_max = Type.registry_get_max_()
    funcs = [generate(Type.registry_get_ptr_(i+1)) for i in range(n_inst_max)]

    # Reinterpret array of pointers into an array of indices
    index_type = getattr(_modules.get(Type.__module__), 'UInt32')
    indices = _dr.reinterpret_array_v(index_type, instances)

    return _dr.switch(indices-1, funcs, *args)

from drjit import Dynamic, Exception, VarType
import drjit as _dr
import weakref as _wr


def _check1(a0):
    s0 = len(a0)
    ar = a0.empty_(s0 if a0.Size == Dynamic else 0)
    return (ar, s0)


def _check2(a0, a1):
    """Validate the inputs of a binary generic array operation"""
    s0, s1 = len(a0), len(a1)
    sr = max(s0, s1)
    if (s0 != sr and s0 != 1) or (s1 != sr and s1 != 1):
        raise Exception("Incompatible argument sizes: %i and %i" % (s0, s1))
    elif type(a0) is not type(a1):  # noqa
        raise Exception("Type mismatch!")
    ar = a0.empty_(sr if a0.Size == Dynamic else 0)
    return (ar, sr)


def _check2_inplace(a0, a1):
    """Validate the inputs of a binary generic array operation (in-place)"""
    s0, s1 = len(a0), len(a1)
    sr = max(s0, s1)
    if s0 != sr or (s1 != sr and s1 != 1):
        raise Exception("Incompatible argument sizes: %i and %i" % (s0, s1))
    elif type(a0) is not type(a1):  # noqa
        raise Exception("Type mismatch!")
    return sr


def _check2_bitop(a0, a1):
    """Validate the inputs of a binary bit manipulation array operation"""
    s0, s1 = len(a0), len(a1)
    sr = max(s0, s1)
    if (s0 != sr and s0 != 1) or (s1 != sr and s1 != 1):
        raise Exception("Incompatible argument sizes: %i and %i" % (s0, s1))
    elif type(a0) is not type(a1) and type(a1) is not a0.MaskType:  # noqa
        raise Exception("Type mismatch!")
    ar = a0.empty_(sr if a0.Size == Dynamic else 0)
    return (ar, sr)


def _check2_bitop_inplace(a0, a1):
    """Validate the inputs of a binary bit manipulation array operation
       (in-place)"""
    s0, s1 = len(a0), len(a1)
    sr = max(s0, s1)
    if s0 != sr or (s1 != sr and s1 != 1):
        raise Exception("Incompatible argument sizes: %i and %i" % (s0, s1))
    elif type(a0) is not type(a1) and type(a1) is not a0.MaskType:  # noqa
        raise Exception("Type mismatch!")
    return sr


def _check2_mask(a0, a1):
    """Validate the inputs of a binary mask-producing array operation"""
    s0, s1 = len(a0), len(a1)
    sr = max(s0, s1)
    if (s0 != sr and s0 != 1) or (s1 != sr and s1 != 1):
        raise Exception("Incompatible argument sizes: %i and %i" % (s0, s1))
    elif type(a0) is not type(a1):  # noqa
        raise Exception("Type mismatch!")
    ar = a0.MaskType.empty_(sr if a0.Size == Dynamic else 0)
    return (ar, sr)


def _check3(a0, a1, a2):
    """Validate the inputs of a ternary generic array operation"""
    s0, s1, s2 = len(a0), len(a1), len(a2)
    sr = max(s0, s1, s2)
    if (s0 != sr and s0 != 1) or (s1 != sr and s1 != 1) or \
       (s2 != sr and s2 != 1):
        raise Exception("Incompatible argument sizes: %i, %i, and %i"
                        % (s0, s1, s2))
    elif type(a0) is not type(a1) or type(a2) is not type(a2):  # noqa
        raise Exception("Type mismatch!")
    ar = a0.empty_(sr if a0.Size == Dynamic else 0)
    return (ar, sr)


def _check3_select(a0, a1, a2):
    """Validate the inputs of a select() array operation"""
    s0, s1, s2 = len(a0), len(a1), len(a2)
    sr = max(s0, s1, s2)
    if (s0 != sr and s0 != 1) or (s1 != sr and s1 != 1) or \
       (s2 != sr and s2 != 1):
        raise Exception("Incompatible argument sizes: %i, %i, and %i"
                        % (s0, s1, s2))
    elif type(a1) is not type(a2) or type(a0) is not type(a1).MaskType:  # noqa
        raise Exception("Type mismatch!")
    ar = a1.empty_(sr if a0.Size == Dynamic else 0)
    return (ar, sr)


def _binary_op(a, b, fn):
    """
    Perform a bit-level operation 'fn' involving variables 'a' and 'b' in a way
    that works even when the operands are floating point variables
    """

    convert = isinstance(a, float) or isinstance(b, float)

    if convert:
        src, dst = VarType.Float64, VarType.Int64
        a = _dr.detail.reinterpret_scalar(a, src, dst)
        if isinstance(b, bool):
            b = -1 if b else 0
        else:
            b = _dr.detail.reinterpret_scalar(b, src, dst)

    c = fn(a, b)

    if convert:
        c = _dr.detail.reinterpret_scalar(c, dst, src)

    return c

