                for val_i, i in enumerate(indexes):
                    curr_index = i - only_removed
                    del self[curr_index]
                    if val_i < len(value):
                        self.insert(curr_index, value[val_i])
                    else:
                        only_removed += 1

                # Insert any remaining input items
                for val_i in range(val_i + 1, len(value)):
                    curr_index += 1
                    self.insert(curr_index, value[val_i])
